test('every day in order', () => {
  const names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  names.forEach((name, i) => expect(dayName(i + 1)).toBe(name));
});
test('zero and negative numbers are invalid', () => {
  expect(dayName(0)).toBe('Invalid');
  expect(dayName(-1)).toBe('Invalid');
});
test('the number right after the range is invalid', () => {
  expect(dayName(8)).toBe('Invalid');
});
test('numbers that are not whole are invalid', () => {
  expect(dayName(1.5)).toBe('Invalid');
});

solutions.code:
function dayName(number) {
  switch (number) {
    case 1:
      return 'Monday';
    case 2:
      return 'Tuesday';
    case 3:
      return 'Wednesday';
    case 4:
      return 'Thursday';
    case 5:
      return 'Friday';
    case 6:
      return 'Saturday';
    case 7:
      return 'Sunday';
    default:
      return 'Invalid';
  }
}
